"""Inspect the workspace: list files and describe any SQLite databases found."""
import os
import sqlite3
import sys


def main() -> None:
    print("CWD:", os.getcwd())
    print("\n--- Files in workspace ---")
    for name in sorted(os.listdir(".")):
        size = os.path.getsize(name) if os.path.isfile(name) else "<dir>"
        print(f"  {name}  ({size} bytes)")

    db_files = [
        name
        for name in sorted(os.listdir("."))
        if os.path.isfile(name) and name.lower().endswith(".db")
    ]

    for db_name in db_files:
        print(f"\n--- Schema for {db_name} ---")
        with sqlite3.connect(db_name) as conn:
            cur = conn.cursor()
            cur.execute(
                "SELECT name, type, sql FROM sqlite_master "
                "WHERE type IN ('table', 'index') ORDER BY type, name"
            )
            for name, kind, sql in cur.fetchall():
                print(f"\n[{kind}] {name}")
                if sql:
                    print(sql)
                # Show columns for tables
                if kind == "table":
                    cur.execute(f'PRAGMA table_info("{name}")')
                    cols = cur.fetchall()
                    print("  columns:", cols)

    if not db_files:
        print("\nNo .db files found.")


if __name__ == "__main__":
    sys.exit(main())

